// Commit message hygiene check.
//
// Usage:
//   pnpm check:commits [--range <rev-range>] | --message <text> | --file <path>
//   pnpm check:commits --help
//
// Without --message or --file, every commit in the range (default: HEAD) is checked.
// Exit codes: 0 pass, 1 violation, 2 usage or environment error.
//
// Merge/revert rule: headers generated by git ("Merge branch|pull request|remote-tracking
// branch|tag|commit ..." and `Revert "..."`) are exempt from the format check (a).
// GitHub's synthetic pull request merge subject "Merge <40-hex sha> into <40-hex sha>" is exempt too.
// The attribution check (b) applies to every message without exemption.
// Other headers such as fixup! or squash! are rejected.

import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

export const COMMIT_TYPES = ['feat', 'fix', 'docs', 'style', 'refactor', 'perf', 'test', 'build', 'ci', 'chore', 'revert'] as const

export const HEADER_PATTERN = /^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([^()\r\n]+\))?!?: \S.*$/

export const AUTO_HEADER_PATTERN = /^(Merge (branch|pull request|remote-tracking branch|tag|commit) |Merge [0-9a-f]{40} into [0-9a-f]{40}$|Revert ")/

export const ATTRIBUTION_PATTERNS: readonly RegExp[] = [
  /^co-authored-by:.*\b(claude|anthropic)\b/im,
  /generated (with|by)\s+\[?claude\b/i,
  /noreply@anthropic\.com/i,
  /claude\.ai\/code/i,
]

const USAGE = [
  'Usage: pnpm check:commits [--range <rev-range>] | --message <text> | --file <path>',
  '',
  'Checks commit messages against the Conventional Commits format and rejects Claude authorship attribution.',
  'Without --message or --file, every commit in the range (default: HEAD) is checked.',
  'Exit codes: 0 pass, 1 violation, 2 usage or environment error.',
  '',
].join('\n')

type Target = { label: string; message: string }

export function stripComments(raw: string): string {
  return raw
    .split(/\r?\n/)
    .filter((line) => !line.startsWith('#'))
    .join('\n')
}

function headerOf(message: string): string | undefined {
  const line = message.split(/\r?\n/).find((l) => l.trim() !== '')
  return line?.trimEnd()
}

export function checkMessage(message: string): string[] {
  const header = headerOf(message)
  if (header === undefined) return ['empty commit message']
  const reasons: string[] = []
  if (!AUTO_HEADER_PATTERN.test(header) && !HEADER_PATTERN.test(header)) {
    reasons.push(
      'header is not Conventional Commits: expected "type(scope)?!?: subject" with type one of ' + COMMIT_TYPES.join(', '),
    )
  }
  const lines = message.split(/\r?\n/)
  for (const pattern of ATTRIBUTION_PATTERNS) {
    const line = lines.find((l) => pattern.test(l))
    if (line !== undefined) {
      reasons.push('contains Claude authorship/session attribution: "' + line.trim() + '"')
    }
  }
  return reasons
}

function report(targets: readonly Target[]): number {
  let violations = 0
  for (const target of targets) {
    const reasons = checkMessage(target.message)
    if (reasons.length === 0) continue
    violations++
    process.stderr.write(`${target.label}: ${headerOf(target.message) ?? ''}\n`)
    for (const reason of reasons) process.stderr.write(`  - ${reason}\n`)
  }
  process.stdout.write(`checked ${targets.length} message(s), ${violations} violation(s)\n`)
  return violations > 0 ? 1 : 0
}

export function main(argv: readonly string[], cwd: string = process.cwd()): number {
  const targets: Target[] = []
  let range: string | undefined
  let inline = false
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i]
    const value = argv[i + 1]
    if (arg === '--help') {
      process.stdout.write(USAGE)
      return 0
    }
    if (arg === '--message' && value !== undefined) {
      targets.push({ label: 'message', message: value })
      inline = true
      i++
    } else if (arg === '--file' && value !== undefined) {
      let content: string
      try {
        content = readFileSync(resolve(cwd, value), 'utf8')
      } catch {
        process.stderr.write(`cannot read file: ${value}\n`)
        return 2
      }
      targets.push({ label: value, message: stripComments(content) })
      inline = true
      i++
    } else if (arg === '--range' && value !== undefined) {
      range = value
      i++
    } else {
      process.stderr.write(USAGE)
      return 2
    }
  }
  if (inline) return report(targets)

  const git = (args: string[]): string =>
    execFileSync('git', args, { cwd, stdio: 'pipe', encoding: 'utf8' })
  try {
    git(['rev-parse', '--is-inside-work-tree'])
  } catch {
    process.stderr.write(`not a git repository: ${cwd}\n`)
    return 2
  }
  if (range === undefined) {
    try {
      git(['rev-parse', '--verify', '--quiet', 'HEAD'])
    } catch {
      process.stdout.write('no commits to check\n')
      return 0
    }
  }
  let output: string
  try {
    output = git(['log', '--format=%H%x1f%B%x1e', range ?? 'HEAD'])
  } catch (error) {
    process.stderr.write(`git log failed: ${error instanceof Error ? error.message : String(error)}\n`)
    return 2
  }
  const entries = output
    .split('\x1e')
    .map((entry) => entry.trim())
    .filter((entry) => entry !== '')
  for (const entry of entries) {
    const sep = entry.indexOf('\x1f')
    const sha = entry.slice(0, sep)
    const body = entry.slice(sep + 1)
    targets.push({ label: sha.slice(0, 7), message: body })
  }
  return report(targets)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main(process.argv.slice(2))
}
